      s += `<rect x="${C - 15}" y="20" width="30" height="30" rx="7" fill="#fff" stroke="#1a0b2e" stroke-width="2.4"/>`;
      if (k === 'ch') s += `<text x="${C}" y="45" text-anchor="middle" font-family="Arial Black,Arial,sans-serif" font-weight="900" font-size="26" fill="${COL.ch}">?</text>`;
      else s += (k === 'b2' ? [5, 7] : [2, 4]).map((n) => `<circle cx="${C + ((n % 3) - 1) * 8.5}" cy="${35 + (Math.floor(n / 3) - 1) * 8.5}" r="3.3" fill="#141414"/>`).join('') + (k === 'b4' ? `<circle cx="${C - 8.5}" cy="${35 + 8.5}" r="3.3" fill="#141414"/><circle cx="${C + 8.5}" cy="${35 - 8.5}" r="3.3" fill="#141414"/>` : '');
